  prepareFrame(frameState) {
    // Try to share a single WebGLHelper per map
    if (!this.helper && !!this.getLayer().getSource()) {
      let map = frameState.map;
      if (map) {
        let sharedHelper = mapWebGLHelperRegistry.get(map);
        if (!sharedHelper) {
          sharedHelper = new WebGLHelper({
            postProcesses: this.postProcesses_,
            uniforms: this.uniforms_,
          });
          // Mark as shared so we don't dispose it from a single renderer
          sharedHelper._ol_isSharedHelper = true;
          mapWebGLHelperRegistry.set(map, sharedHelper);
